import json
import re
import sys

# HTTP evidence is independent from strict organization identity inspection.
# The connector contract supplies an integral HTTP status and Boolean success.
try:
    httpStatus = int(sys.argv[4])
except (ValueError, TypeError):
    httpStatus = 0
requestSucceeded = sys.argv[5].strip().lower() == "true"
if not requestSucceeded or httpStatus != 200:
    statusCode = httpStatus if 300 <= httpStatus < 600 else 502
    lookupStatus = "api-failure"
    message = "Organization lookup API request failed"
    errorMessage = "The organization request failed or returned a non-200 response."
    organizationMoid, organizationJson, inspectionComplete = "", "{}", False
    safeCode, safeMessage = "", ""
    try:
        payload = json.loads(sys.argv[1])
        # Preserve the native String projection used by the old safe allowlists.
        def text(value):
            return value if isinstance(value, str) else json.dumps(value, separators=(",", ":"), ensure_ascii=False)
        code = text(payload["Code"]) if isinstance(payload, dict) and "Code" in payload else ""
        detail = text(payload["Message"]) if isinstance(payload, dict) and "Message" in payload else ""
        if re.fullmatch(r"[A-Za-z0-9_.:-]{1,128}", code):
            safeCode = code
        if re.fullmatch(r"[A-Za-z0-9 _.,:()/+\-]{1,500}", detail) and not re.search(r"authorization|password|secret|token|api.?key|bearer|https?://", detail, re.IGNORECASE):
            safeMessage = detail
    except Exception:
        pass
    if safeMessage:
        errorMessage = safeMessage
    resultJson = json.dumps({"status":"api-failure", "upstreamStatus":httpStatus, "Code":safeCode, "Message":safeMessage}, separators=(",", ":"))
else:
    import json
    import re
    import sys
    statusCode, lookupStatus, message = 502, "invalid-response", "Organization response is invalid"
    organizationMoid, organizationJson = "", "{}"
    inspectionComplete = False
    try:
        payload = json.loads(sys.argv[1])
        if not isinstance(payload, dict): raise ValueError("Organization response must be an object")
        count, rows = payload.get("Count"), payload.get("Results")
        if isinstance(count, bool) or not isinstance(count, int) or count < 0: raise ValueError("Count must be a nonnegative integer")
        if not isinstance(rows, list): raise ValueError("Results must be an array")
        if count != len(rows): raise ValueError("Count and Results length differ; the bounded page is incomplete")
        if count > 2: raise ValueError("Count exceeds the two-row lookup bound")
        if count == 0: statusCode, lookupStatus, message = 404, "not-found", "No organization matched the exact requested name"
        elif count != 1: statusCode, lookupStatus, message = 409, "ambiguous", "More than one organization matched the exact requested name"
        else:
            item = rows[0]
            if not isinstance(item, dict) or item.get("Name") != sys.argv[2]: raise ValueError("Organization Name does not match exactly")
            if item.get("ObjectType") != "organization.Organization" or item.get("ClassId") != "organization.Organization": raise ValueError("Organization discriminators do not match")
            moid = item.get("Moid")
            pattern = r"[0-9a-fA-F]{24}" if sys.argv[3] == "Hex24" else r"[A-Za-z0-9][A-Za-z0-9._~-]{0,127}"
            if not isinstance(moid, str) or re.fullmatch(pattern, moid) is None: raise ValueError("Organization Moid is missing or malformed")
            organizationMoid = moid
            projected = {key:item[key] for key in ("Moid", "Name", "ObjectType", "ClassId")}
            organizationJson = json.dumps(projected, separators=(",", ":"))
            resultJson = json.dumps({"Count":1,"Results":[projected]}, separators=(",", ":"))
            statusCode, lookupStatus, message = 200, "exact", "Organization resolved exactly"
        inspectionComplete = True
    except Exception as exc:
        statusCode, lookupStatus, message, inspectionComplete = 502, "invalid-response", str(exc), True
    errorMessage = "" if statusCode == 200 else message
    if statusCode != 200: resultJson = json.dumps({"status":lookupStatus,"error":message}, separators=(",", ":"))

import json
import sys

safetyValidationStatus = "helper-failure"
safetyValidationStatusCode = "500"
safetyValidationMessage = "Pre-mutation Recommission safety validation did not complete."
validatedSafetySummaryJson = json.dumps({"error": safetyValidationMessage}, separators=(",", ":"))
validatedRequestBodyJson = json.dumps({"error": safetyValidationMessage}, separators=(",", ":"))

try:
    summary = json.loads(sys.argv[1])
    rawIdentifier = int(sys.argv[2])
    deviceType, formFactor = sys.argv[3], sys.argv[4]
    expectedName, expectedOrganizationMoid = sys.argv[5], sys.argv[6]
    expectedMoid, expectedObjectType = sys.argv[7], sys.argv[8]
    expectedPreAdminState, expectedPreLifecycle = sys.argv[9], sys.argv[10]
    identifierRequestedText, identifierValueText = sys.argv[11], sys.argv[12]
    if identifierRequestedText not in ("true", "false"):
        raise ValueError("The normalized Identifier request flag is invalid.")
    identifierRequested = identifierRequestedText == "true"
    identifierValue = int(identifierValueText)
    requiredKeys = {
        "action", "deviceType", "serverFormFactor", "Moid", "Name", "Serial", "Model",
        "ObjectType", "PermissionResourceMoid", "preActionAdminActionState", "preActionLifecycle",
        "preActionIdentifier", "identifierRequested", "requestedIdentifier"
    }
    if not isinstance(summary, dict):
        raise ValueError("The pre-mutation safety summary is not a JSON object.")
    if set(summary.keys()) != requiredKeys:
        raise ValueError("The pre-mutation safety summary fields do not match the exact required contract.")
    if summary.get("action") != "Recommission":
        raise ValueError("The safety summary action is not Recommission.")
    if summary.get("deviceType") != deviceType or summary.get("serverFormFactor") != formFactor:
        raise ValueError("The safety summary route does not match the validated device route.")
    if summary.get("Name") != expectedName or summary.get("Moid") != expectedMoid or summary.get("ObjectType") != expectedObjectType:
        raise ValueError("The safety summary identity does not match the exact resolved identity.")
    if summary.get("PermissionResourceMoid") != expectedOrganizationMoid:
        raise ValueError("The safety summary organization does not match the resolved organization.")
    if summary.get("preActionAdminActionState") != expectedPreAdminState or summary.get("preActionLifecycle") != expectedPreLifecycle:
        raise ValueError("The safety summary pre-action state does not match the captured identity state.")
    if expectedPreLifecycle != "Decommissioned":
        raise ValueError("The required pre-action Lifecycle=Decommissioned condition is not present.")
    if not isinstance(summary.get("Serial"), str) or not summary["Serial"].strip():
        raise ValueError("The safety summary Serial is missing.")
    if not isinstance(summary.get("Model"), str) or not summary["Model"].strip():
        raise ValueError("The safety summary Model is missing.")
    preIdentifier = summary.get("preActionIdentifier")
    if preIdentifier is not None and (isinstance(preIdentifier, bool) or not isinstance(preIdentifier, int) or preIdentifier < 1):
        raise ValueError("The safety summary pre-action Identifier is invalid.")
    allowedTypes = {"equipment.ChassisIdentity"} if deviceType == "Chassis" else ({"compute.BladeIdentity"} if formFactor == "Blade" else ({"compute.RackUnitIdentity"} if formFactor == "Rack Unit" else {"compute.BladeIdentity", "compute.RackUnitIdentity"}))
    if expectedObjectType not in allowedTypes:
        raise ValueError("The resolved identity ObjectType is inconsistent with the validated route.")
    if summary.get("identifierRequested") is not identifierRequested:
        raise ValueError("The safety summary Identifier request flag is inconsistent.")
    if identifierRequested:
        if rawIdentifier < 1 or identifierValue != rawIdentifier:
            raise ValueError("The requested Identifier does not match the positive raw workflow input.")
        if summary.get("requestedIdentifier") != identifierValue:
            raise ValueError("The safety summary requested Identifier is inconsistent.")
        if expectedObjectType not in ("compute.RackUnitIdentity", "equipment.ChassisIdentity"):
            raise ValueError("Identifier cannot be included for the resolved identity type.")
        requestBody = {"AdminAction": "Recommission", "Identifier": identifierValue}
    else:
        if rawIdentifier != 0 or identifierValue != 0 or summary.get("requestedIdentifier") is not None:
            raise ValueError("An omitted Identifier must remain 0 internally and null in the safety summary.")
        requestBody = {"AdminAction": "Recommission"}
    if expectedObjectType == "compute.BladeIdentity" and set(requestBody.keys()) != {"AdminAction"}:
        raise ValueError("A Blade recommission body must omit Identifier.")
    validatedSafetySummaryJson = json.dumps(summary, separators=(",", ":"))
    validatedRequestBodyJson = json.dumps(requestBody, separators=(",", ":"))
    safetyValidationStatus = "ready"
    safetyValidationStatusCode = "200"
    safetyValidationMessage = "The exact pre-mutation Recommission safety summary and conditional request body are complete and internally consistent."
except Exception as exc:
    safetyValidationStatus = "helper-failure"
    safetyValidationStatusCode = "500"
    safetyValidationMessage = str(exc)
    validatedSafetySummaryJson = json.dumps({"error": "Pre-mutation Recommission safety validation failed", "detail": safetyValidationMessage}, separators=(",", ":"))
    validatedRequestBodyJson = json.dumps({"error": "Recommission request body construction failed", "detail": safetyValidationMessage}, separators=(",", ":"))
